{"command": "str_replace", "new_str": "/// The planner builds an execution plan from a parsed Abstract Syntax Tree,
/// using the catalog for schema information.
pub struct Planner<'a, C: Catalog> {
    catalog: &'a C,
}

impl<'a, C: Catalog> Planner<'a, C> {
    /// Creates a new planner.
    pub fn new(catalog: &'a C) -> Self {
        Self { catalog }
    }

    /// Builds a plan for an AST statement.
    pub fn build(&mut self, statement: ast::Statement) -> Result<Plan> {
        match statement {
            ast::Statement::CreateTable { name, columns } => {
                self.build_create_table(name, columns)
            }
            ast::Statement::DropTable { name, if_exists } => {
                self.build_drop_table(name, if_exists)
            }
            ast::Statement::Delete { table, r#where } => {
                self.build_delete(table, r#where)
            }
            ast::Statement::Insert { table, columns, values } => {
                self.build_insert(table, columns, values)
            }
            ast::Statement::Update { table, set, r#where } => {
                self.build_update(table, set, r#where)
            }
            ast::Statement::Select { select, from, r#where, group_by, having, order_by, offset, limit } => {
                self.build_select(select, from, r#where, group_by, having, order_by, offset, limit)
            }
            _ => Err(errinput!("unexpected statement type")),
        }
    }

    /// Builds a CREATE TABLE plan.
    fn build_create_table(&self, name: String, columns: Vec<ast::Column>) -> Result<Plan> {
        let mut cols = Vec::new();
        let mut primary_key_index = None;
        let mut primary_key_count = 0;

        for (i, col) in columns.into_iter().enumerate() {
            if col.primary_key {
                primary_key_count += 1;
                primary_key_index = Some(i);
            }
            cols.push(Column {
                name: col.name,
                datatype: col.datatype,
                primary_key: col.primary_key,
                nullable: col.nullable,
                default: col.default.map(|e| self.build_expression(e, &Scope::new())?).ok(),
                unique: col.unique,
                index: col.index,
                references: col.references,
            });
        }

        if primary_key_count == 0 {
            return Err(errinput!("table must have a primary key"));
        }
        if primary_key_count > 1 {
            return Err(errinput!("table can only have one primary key"));
        }

        let table = Table {
            name,
            columns: cols,
            primary_key: primary_key_index.unwrap(),
        };

        Ok(Plan::CreateTable { schema: table })
    }

    /// Builds a DROP TABLE plan.
    fn build_drop_table(&self, name: String, if_exists: bool) -> Result<Plan> {
        Ok(Plan::DropTable { name, if_exists })
    }

    /// Builds a DELETE plan.
    fn build_delete(&self, table: String, r#where: Option<ast::Expression>) -> Result<Plan> {
        let table = self.catalog.must_get_table(&table)?;
        let primary_key = table.primary_key;

        let mut scope = Scope::from_table(&table)?;
        let predicate = if let Some(expr) = r#where {
            Some(self.build_expression(expr, &mut scope)?)
        } else {
            None
        };

        let source = Node::Scan {
            table: table.clone(),
            filter: predicate,
            alias: None,
        };

        Ok(Plan::Delete { table, primary_key, source })
    }

    /// Builds an INSERT plan.
    fn build_insert(
        &self,
        table: String,
        columns: Option<Vec<String>>,
        values: Vec<Vec<ast::Expression>>,
    ) -> Result<Plan> {
        let table = self.catalog.must_get_table(&table)?;
        let column_map = if let Some(cols) = columns {
            let mut map = HashMap::new();
            for (i, col_name) in cols.into_iter().enumerate() {
                if let Some(col_idx) = table.column_index(&col_name) {
                    map.insert(col_idx, i);
                } else {
                    return Err(errinput!("unknown column {col_name}"));
                }
            }
            Some(map)
        } else {
            None
        };

        Ok(Plan::Insert {
            table,
            column_map,
            source: Node::Values { rows: values },
        })
    }

    /// Builds an UPDATE plan.
    fn build_update(
        &self,
        table: String,
        set: BTreeMap<String, Option<ast::Expression>>,
        r#where: Option<ast::Expression>,
    ) -> Result<Plan> {
        let table = self.catalog.must_get_table(&table)?;
        let primary_key = table.primary_key;

        let mut scope = Scope::from_table(&table)?;
        let predicate = if let Some(expr) = r#where {
            Some(self.build_expression(expr, &mut scope)?)
        } else {
            None
        };

        let mut expressions = Vec::new();
        for (col_name, value) in set {
            if let Some(col_idx) = table.column_index(&col_name) {
                let expr = if let Some(expr) = value {
                    Some(self.build_expression(expr, &mut scope)?)
                } else {
                    None
                };
                expressions.push((col_idx, expr));
            } else {
                return Err(errinput!("unknown column {col_name}"));
            }
        }

        let source = Node::Scan {
            table: table.clone(),
            filter: predicate,
            alias: None,
        };

        Ok(Plan::Update { table, primary_key, source, expressions })
    }

    /// Builds a SELECT plan.
    #[allow(clippy::too_many_arguments)]
    fn build_select(
        &self,
        mut select: Vec<(ast::Expression, Option<String>)>,
        from: Vec<ast::From>,
        r#where: Option<ast::Expression>,
        group_by: Vec<ast::Expression>,
        having: Option<ast::Expression>,
        order_by: Vec<(ast::Expression, ast::Direction)>,
        offset: Option<ast::Expression>,
        limit: Option<ast::Expression>,
    ) -> Result<Plan> {
        let mut scope = Scope::new();
        let source = self.build_from_clause(from, &mut scope)?;

        // Collect aggregates from SELECT, HAVING, and ORDER BY
        let aggregates = self.collect_aggregates(&select, &having, &order_by);

        // Build hidden columns for downstream nodes
        let hidden = self.build_select_hidden(&having, &order_by, &scope, &mut scope);

        // Build the source node with hidden columns
        let source = if !hidden.is_empty() {
            Node::Projection {
                source: Box::new(source),
                expressions: hidden,
                aliases: vec![],
            }
        } else {
            source
        };

        // Build WHERE filter
        let filter = if let Some(expr) = r#where {
            Some(self.build_expression(expr, &mut scope)?)
        } else {
            None
        };

        // Build HAVING filter
        let having_filter = if let Some(expr) = having {
            Some(self.build_expression(expr, &mut scope)?)
        } else {
            None
        };

        // Build GROUP BY
        let group_by_exprs: Vec<Expression> = group_by
            .into_iter()
            .map(|e| self.build_expression(e, &mut scope))
            .collect::<Result<_>>()?;

        // Build aggregates
        let aggregates: Vec<Aggregate> = aggregates
            .into_iter()
            .map(|e| self.build_aggregate_function(e, &scope))
            .collect::<Result<_>>()?;

        // Build ORDER BY
        let order_by_exprs: Vec<(Expression, Direction)> = order_by
            .into_iter()
            .map(|(e, d)| Ok((self.build_expression(e, &mut scope)?, d.into())))
            .collect::<Result<_>>()?;

        // Build OFFSET
        let offset_expr = offset.map(|e| self.build_expression(e, &mut scope)).transpose()?;

        // Build LIMIT
        let limit_expr = limit.map(|e| self.build_expression(e, &mut scope)).transpose()?;

        // Build the plan
        let mut node = source;

        // Apply filter
        if let Some(filter) = filter {
            node = Node::Filter {
                source: Box::new(node),
                predicate: filter,
            };
        }

        // Apply aggregation
        if !aggregates.is_empty() || !group_by_exprs.is_empty() {
            node = Node::Aggregate {
                source: Box::new(node),
                group_by: group_by_exprs,
                aggregates,
            };
        }

        // Apply HAVING filter
        if let Some(having_filter) = having_filter {
            node = Node::Filter {
                source: Box::new(node),
                predicate: having_filter,
            };
        }

        // Apply ORDER BY
        if !order_by_exprs.is_empty() {
            node = Node::Order {
                source: Box::new(node),
                key: order_by_exprs,
            };
        }

        // Apply OFFSET
        if let Some(expr) = offset_expr {
            let offset_val = self.build_constant_value(expr)?;
            if let Value::Integer(offset) = offset_val {
                node = Node::Offset {
                    source: Box::new(node),
                    offset: offset as usize,
                };
            }
        }

        // Apply LIMIT
        if let Some(expr) = limit_expr {
            let limit_val = self.build_constant_value(expr)?;
            if let Value::Integer(limit) = limit_val {
                node = Node::Limit {
                    source: Box::new(node),
                    limit: limit as usize,
                };
            }
        }

        // Build projection
        let (expressions, aliases): (Vec<Expression>, Vec<Label>) = select
            .into_iter()
            .map(|(expr, alias)| {
                let expr = self.build_expression(expr, &mut scope)?;
                let label = alias.map(Label::from).unwrap_or_else(|| {
                    // Use expression display as label
                    Label::from(expr.display(&node))
                });
                Ok((expr, label))
            })
            .collect::<Result<_>>()?
            .into_iter()
            .unzip();

        let node = Node::Projection {
            source: Box::new(node),
            expressions,
            aliases,
        };

        Ok(Plan::Select(node))
    }

    /// Builds a FROM clause consisting of one or more items.
    fn build_from_clause(&self, from: Vec<ast::From>, scope: &mut Scope) -> Result<Node> {
        if from.is_empty() {
            return Ok(Node::Nothing { columns: vec![] });
        }

        let mut node = self.build_from(from[0].clone(), scope)?;

        for item in from.iter().skip(1) {
            match item {
                ast::From::Table { name, alias } => {
                    let table = self.catalog.must_get_table(name)?;
                    let mut child_scope = Scope::from_table(&table)?;
                    scope.merge(child_scope.clone())?;
                    let child_node = Node::Scan {
                        table,
                        filter: None,
                        alias: alias.clone(),
                    };
                    node = Node::NestedLoopJoin {
                        left: Box::new(node),
                        right: Box::new(child_node),
                        predicate: None,
                        outer: false,
                    };
                    *scope = child_scope;
                }
                ast::From::Join { left, right, r#type, predicate } => {
                    let left_scope = scope.clone();
                    let left_node = self.build_from(*left, scope)?;
                    let right_node = self.build_from(*right, scope)?;
                    let predicate = if let Some(expr) = predicate {
                        Some(self.build_expression(expr, scope)?)
                    } else {
                        None
                    };
                    node = match r#type {
                        ast::JoinType::Cross => Node::NestedLoopJoin {
                            left: Box::new(left_node),
                            right: Box::new(right_node),
                            predicate: None,
                            outer: false,
                        },
                        ast::JoinType::Inner => Node::NestedLoopJoin {
                            left: Box::new(left_node),
                            right: Box::new(right_node),
                            predicate,
                            outer: false,
                        },
                        ast::JoinType::Left => Node::NestedLoopJoin {
                            left: Box::new(left_node),
                            right: Box::new(right_node),
                            predicate,
                            outer: true,
                        },
                        ast::JoinType::Right => Node::NestedLoopJoin {
                            left: Box::new(left_node),
                            right: Box::new(right_node),
                            predicate,
                            outer: true,
                        },
                    };
                    scope = &left_scope;
                }
            }
        }

        Ok(node)
    }

    /// Builds FROM items, which can either be a single table or a chained join
    /// of multiple tables.
    fn build_from(&self, from: ast::From, parent_scope: &mut Scope) -> Result<Node> {
        match from {
            ast::From::Table { name, alias } => {
                let table = self.catalog.must_get_table(&name)?;
                let mut child_scope = Scope::from_table(&table)?;
                parent_scope.merge(child_scope.clone())?;
                Ok(Node::Scan {
                    table,
                    filter: None,
                    alias,
                })
            }
            ast::From::Join { left, right, r#type, predicate } => {
                let left_node = self.build_from(*left, parent_scope)?;
                let right_node = self.build_from(*right, parent_scope)?;
                let predicate = if let Some(expr) = predicate {
                    Some(self.build_expression(expr, parent_scope)?)
                } else {
                    None
                };
                Ok(Node::NestedLoopJoin {
                    left: Box::new(left_node),
                    right: Box::new(right_node),
                    predicate,
                    outer: r#type.is_outer(),
                })
            }
        }
    }

    /// Builds an aggregate node.
    fn build_aggregate(
        &self,
        source: Node,
        mut group_by: Vec<ast::Expression>,
        mut aggregates: Vec<ast::Expression>,
        scope: &mut Scope,
    ) -> Result<Node> {
        let group_by_exprs: Vec<Expression> = group_by
            .drain(..)
            .map(|e| self.build_expression(e, scope))
            .collect::<Result<_>>()?;

        let aggregates: Vec<Aggregate> = aggregates
            .drain(..)
            .map(|e| self.build_aggregate_function(e, scope))
            .collect::<Result<_>>()?;

        Ok(Node::Aggregate {
            source: Box::new(source),
            group_by: group_by_exprs,
            aggregates,
        })
    }

    /// Builds an aggregate function from an AST expression.
    fn build_aggregate_function(expr: ast::Expression, scope: &Scope) -> Result<Aggregate> {
        use ast::Expression::*;
        use ast::Operator::*;

        match expr {
            Operator(op) => match *op {
                Function(ref name, ref args) => {
                    let name = name.to_uppercase();
                    let inner = if args.len() == 1 {
                        Some(Self::build_expression(args[0].clone(), scope)?)
                    } else {
                        None
                    };
                    match name.as_str() {
                        "COUNT" => {
                            if let Some(expr) = inner {
                                Ok(Aggregate::Count(expr))
                            } else {
                                Err(errinput!("COUNT requires one argument"))
                            }
                        }
                        "SUM" => {
                            if let Some(expr) = inner {
                                Ok(Aggregate::Sum(expr))
                            } else {
                                Err(errinput!("SUM requires one argument"))
                            }
                        }
                        "AVG" => {
                            if let Some(expr) = inner {
                                Ok(Aggregate::Average(expr))
                            } else {
                                Err(errinput!("AVG requires one argument"))
                            }
                        }
                        "MAX" => {
                            if let Some(expr) = inner {
                                Ok(Aggregate::Max(expr))
                            } else {
                                Err(errinput!("MAX requires one argument"))
                            }
                        }
                        "MIN" => {
                            if let Some(expr) = inner {
                                Ok(Aggregate::Min(expr))
                            } else {
                                Err(errinput!("MIN requires one argument"))
                            }
                        }
                        "MEDIAN" => {
                            if let Some(expr) = inner {
                                Ok(Aggregate::Median(expr))
                            } else {
                                Err(errinput!("MEDIAN requires one argument"))
                            }
                        }
                        "STRING_AGG" => {
                            if args.len() == 2 {
                                let expr = Self::build_expression(args[0].clone(), scope)?;
                                let delim = Self::build_constant_value(args[1].clone())?;
                                if let Value::String(d) = delim {
                                    Ok(Aggregate::StringAgg(expr, d))
                                } else {
                                    Err(errinput!("STRING_AGG delimiter must be a string"))
                                }
                            } else {
                                Err(errinput!("STRING_AGG requires two arguments"))
                            }
                        }
                        _ => Err(errinput!("unknown aggregate function {name}")),
                    }
                }
                _ => Err(errinput!("expected aggregate function")),
            },
            _ => Err(errinput!("expected aggregate function")),
        }
    }

    /// Checks whether a given AST expression is an aggregate function.
    fn is_aggregate_function(expr: &ast::Expression) -> bool {
        use ast::Expression::*;
        match expr {
            Operator(ast::Operator::Function(name, _)) => {
                matches!(
                    name.to_uppercase().as_str(),
                    "COUNT" | "SUM" | "AVG" | "MAX" | "MIN" | "MEDIAN" | "STRING_AGG"
                )
            }
            _ => false,
        }
    }

    /// Collects aggregate functions from SELECT, HAVING, and ORDER BY clauses.
    fn collect_aggregates(
        select: &[(ast::Expression, Option<String>)],
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
    ) -> Vec<ast::Expression> {
        let mut aggregates = Vec::new();
        for (expr, _) in select {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }
        if let Some(expr) = having {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }
        for (expr, _) in order_by {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }
        aggregates
    }

    /// Builds hidden columns for a projection to pass through columns that are
    /// used by downstream nodes.
    fn build_select_hidden(
        &self,
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
        scope: &Scope,
        child_scope: &mut Scope,
    ) -> Vec<Expression> {
        let mut hidden = Vec::new();

        // Add HAVING expressions
        if let Some(expr) = having {
            expr.walk(&mut |e| {
                if let ast::Expression::Column(table, name) = e {
                    if let Ok(idx) = scope.lookup_column(table.as_deref(), name) {
                        if let Some(label) = scope.column_label(idx) {
                            hidden.push(Expression::Column(idx));
                            child_scope.add_passthrough(scope, idx, false);
                        }
                    }
                }
                true
            });
        }

        // Add ORDER BY expressions
        for (expr, _) in order_by {
            expr.walk(&mut |e| {
                if let ast::Expression::Column(table, name) = e {
                    if let Ok(idx) = scope.lookup_column(table.as_deref(), name) {
                        if let Some(label) = scope.column_label(idx) {
                            hidden.push(Expression::Column(idx));
                            child_scope.add_passthrough(scope, idx, false);
                        }
                    }
                }
                true
            });
        }

        hidden
    }

    /// Builds an expression from an AST expression, looking up columns and
    /// aggregate expressions in the scope.
    pub fn build_expression(expr: ast::Expression, scope: &Scope) -> Result<Expression> {
        use ast::Expression::*;
        use ast::Operator::*;

        Ok(match expr {
            All => return Err(errinput!("* not allowed in this context")),
            Column(table, name) => {
                let idx = scope.lookup_column(table.as_deref(), &name)?;
                Expression::Column(idx)
            }
            Literal(lit) => Expression::Constant(match lit {
                ast::Literal::Null => Value::Null,
                ast::Literal::Boolean(b) => Value::Boolean(b),
                ast::Literal::Integer(i) => Value::Integer(i),
                ast::Literal::Float(f) => Value::Float(f),
                ast::Literal::String(s) => Value::String(s),
            }),
            Operator(op) => match *op {
                And(lhs, rhs) => Expression::And(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                Or(lhs, rhs) => Expression::Or(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                Not(inner) => Expression::Not(Box::new(Self::build_expression(*inner, scope)?)),
                Equal(lhs, rhs) => Expression::Equal(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                NotEqual(lhs, rhs) => Expression::Equal(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                GreaterThan(lhs, rhs) => Expression::GreaterThan(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                GreaterThanOrEqual(lhs, rhs) => {
                    let lhs = Self::build_expression(*lhs, scope)?;
                    let rhs = Self::build_expression(*rhs, scope)?;
                    Expression::Or(
                        Box::new(Expression::Equal(Box::new(lhs), Box::new(rhs))),
                        Box::new(Expression::GreaterThan(
                            Box::new(Self::build_expression(*lhs, scope)?),
                            Box::new(Self::build_expression(*rhs, scope)?),
                        )),
                    )
                }
                LessThan(lhs, rhs) => Expression::LessThan(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                LessThanOrEqual(lhs, rhs) => {
                    let lhs = Self::build_expression(*lhs, scope)?;
                    let rhs = Self::build_expression(*rhs, scope)?;
                    Expression::Or(
                        Box::new(Expression::Equal(Box::new(lhs), Box::new(rhs))),
                        Box::new(Expression::LessThan(
                            Box::new(Self::build_expression(*lhs, scope)?),
                            Box::new(Self::build_expression(*rhs, scope)?),
                        )),
                    )
                }
                Like(lhs, rhs) => Expression::Like(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                Add(lhs, rhs) => Expression::Add(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                Subtract(lhs, rhs) => Expression::Subtract(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                Multiply(lhs, rhs) => Expression::Multiply(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                Divide(lhs, rhs) => Expression::Divide(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                Exponentiate(lhs, rhs) => Expression::Exponentiate(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                Remainder(lhs, rhs) => Expression::Remainder(
                    Box::new(Self::build_expression(*lhs, scope)?),
                    Box::new(Self::build_expression(*rhs, scope)?),
                ),
                Negate(inner) => Expression::Negate(Box::new(Self::build_expression(*inner, scope)?)),
                Identity(inner) => Expression::Identity(Box::new(Self::build_expression(*inner, scope)?)),
                Factorial(inner) => Expression::Factorial(Box::new(Self::build_expression(*inner, scope)?)),
                Is(inner, lit) => {
                    let inner = Self::build_expression(*inner, scope)?;
                    match lit {
                        ast::Literal::Null => Expression::Is(Box::new(inner), Value::Null),
                        _ => return Err(errinput!("unsupported IS value")),
                    }
                }
                IsNot(inner, lit) => {
                    let inner = Self::build_expression(*inner, scope)?;
                    match lit {
                        ast::Literal::Null => Expression::Not(Box::new(Expression::Is(
                            Box::new(inner),
                            Value::Null,
                        ))),
                        _ => return Err(errinput!("unsupported IS NOT value")),
                    }
                }
                Function(name, args) => {
                    // Handle sqrt function
                    if name.to_lowercase() == "sqrt" {
                        if args.len() == 1 {
                            let inner = Self::build_expression(args[0].clone(), scope)?;
                            return Ok(Expression::SquareRoot(Box::new(inner)));
                        } else {
                            return Err(errinput!("sqrt requires one argument"));
                        }
                    }
                    // Handle other scalar functions
                    return Err(errinput!("unknown function {name}"));
                }
            },
            Function(name, args) => {
                // Handle sqrt function
                if name.to_lowercase() == "sqrt" {
                    if args.len() == 1 {
                        let inner = Self::build_expression(args[0].clone(), scope)?;
                        return Ok(Expression::SquareRoot(Box::new(inner)));
                    } else {
                        return Err(errinput!("sqrt requires one argument"));
                    }
                }
                // Handle other scalar functions
                return Err(errinput!("unknown function {name}"));
            }
        })
    }

    /// Builds a constant value from an AST expression by evaluating it.
    fn build_constant_value(expr: ast::Expression) -> Result<Value> {
        use ast::Expression::*;
        use ast::Operator::*;

        match expr {
            Literal(lit) => Ok(match lit {
                ast::Literal::Null => Value::Null,
                ast::Literal::Boolean(b) => Value::Boolean(b),
                ast::Literal::Integer(i) => Value::Integer(i),
                ast::Literal::Float(f) => Value::Float(f),
                ast::Literal::String(s) => Value::String(s),
            }),
            Operator(op) => match *op {
                Negate(inner) => {
